SELECT s.A_STOCKSNAME AS `股票名称`, s.A_STOCKCODE AS `股票代码`, s.PERIODDATE AS `报告期`, s.REG_DATE AS `股权登记日`, s.EX_DIVI_DATE AS `除权除息日` FROM STK_DIV_INFO s JOIN GET_A_SEC_CODE g ON s.COMCODE = g.COMCODE AND g.ISVALID = 1 WHERE s.ISVALID = 1 AND s.A_STOCKSNAME LIKE '%中国神华%' AND s.PERIODDATE >= '2025-01-01' AND s.PERIODDATE < '2026-01-01' ORDER BY s.PRG_CODE DESC, s.DIR_DCL_DATE DESC LIMIT 1;
